class TelegramConversationMetricRecord:
    operation: str
    component: str
    outcome: str
    duration_ms: float
    error_category: str | None = None
    conflict_recovered: bool | None = None

    def __post_init__(self) -> None:
        object.__setattr__(
            self,
            "operation",
            _validate_choice(
                field_name="operation",
                value=self.operation,
                allowed=ALLOWED_METRIC_OPERATIONS,
            ),
        )

        object.__setattr__(
            self,
            "component",
            _validate_choice(
                field_name="component",
                value=self.component,
                allowed=ALLOWED_METRIC_COMPONENTS,
            ),
        )

        object.__setattr__(
            self,
            "outcome",
            _validate_choice(
                field_name="outcome",
                value=self.outcome,
                allowed=ALLOWED_OUTCOMES,
            ),
        )

        object.__setattr__(
            self,
            "duration_ms",
            _validate_duration(
                self.duration_ms
            ),
        )

        if self.error_category is not None:
            object.__setattr__(
                self,
                "error_category",
                _validate_choice(
                    field_name="error_category",
                    value=self.error_category,
                    allowed=ALLOWED_ERROR_CATEGORIES,
                ),
            )

        if (
            self.outcome
            in {
                "error",
                "conflict",
            }
            and self.error_category is None
        ):
            raise ValueError(
                "error_category é obrigatória "
                "para outcomes error ou conflict."
            )

        if (
            self.conflict_recovered is not None
            and self.outcome
            not in {
                "conflict",
                "recovered",
            }
        ):
            raise ValueError(
                "conflict_recovered somente pode ser "
                "usado em conflito ou recuperação."
            )

